		{"abcdef123456", "ab/cdef123456"},
		// Edge cases: short strings (shouldn't happen in practice, but test the fallback)
		{"", ""},
		{"a", "a"},
		{"ab", "ab"},
		{"abc", "ab/c"},
	}

	for _, tt := range tests {
